# Now let me search for each old song on Spotify to get their song_ids
old_song_ids = []
for song in old_songs_parsed:
    query = song['title']
    results = apis.spotify.search_songs(query=query, access_token=spotify_token)
    if results and len(results) > 0:
        # Find the best match by comparing title and artists
        best_match = None
        for result in results:
            result_title = result.get('title', '').lower()
            result_artists = [a.lower() for a in result.get('artists', [])]
            if result_title == song['title'].lower():
                # Check if any artist matches
                song_artists_lower = [a.lower() for a in song['artists']]
                if any(a in result_artists for a in song_artists_lower):
                    best_match = result
                    break
                elif best_match is None:
                    best_match = result
        if best_match:
            old_song_ids.append({
                'song_id': best_match['song_id'],
                'title': best_match['title'],
                'artists': best_match.get('artists', []),
                'original_line': song['original_line']
            })
            print(f"Found: {best_match['song_id']} - {best_match['title']} by {best_match.get('artists', [])}")
        else:
            print(f"No good match for: {song['title']}")
    else:
        print(f"No results for: {song['title']}")

print(f"\nTotal found: {len(old_song_ids)}")

